<?php use App\Core\Authorization; $registrarView=$registrarView??false; ?>
<div class="page-heading"><div><p class="eyebrow">Teacher <?=e($teacher['employee_no'])?></p><h1><?=e($teacher['first_name'].' '.$teacher['last_name'])?></h1><p><span class="badge"><?=e($teacher['employment_status'])?></span></p></div><?php if(Authorization::canEditTeacher((int)$teacher['id'])):?><a class="button primary" href="<?=e(url('/teachers/'.$teacher['id'].'/edit'))?>">Edit profile</a><?php endif;?></div>
<div class="detail-grid">
<section class="card form-section"><h2><?=$registrarView?'Assignment reference':'Profile'?></h2><dl><dt>Department</dt><dd><?=e($teacher['department']?:'—')?></dd><?php if(!$registrarView):?><dt>Email</dt><dd><?=e($teacher['email']?:'—')?></dd><dt>Phone</dt><dd><?=e($teacher['phone']?:'—')?></dd><dt>Hire date</dt><dd><?=e($teacher['hire_date']?:'—')?></dd><dt>Address</dt><dd><?=e($teacher['address']?:'—')?></dd><?php endif;?></dl></section>
<section class="card form-section"><h2>Teaching assignments</h2><?php foreach($assignments as $a):?><p><strong><?=e($a['code'].' — '.$a['name'])?></strong><br><small><?=e($a['school_year'].' · '.$a['grade_level'].' '.$a['section_name'])?><?php if($a['schedule_text']):?> · <?=e($a['schedule_text'])?><?php endif;?><?php if($a['room']):?> · <?=e($a['room'])?><?php endif;?></small></p><?php endforeach;?><?php if(!$assignments):?><p class="empty">No teaching assignments recorded. Assign a subject or adviser section in Academics.</p><?php endif;?></section>
<?php if(Authorization::allows('inventory.view')):?><section class="card form-section profile-inventory"><div class="profile-section-heading"><div><p class="eyebrow">Assigned supplies</p><h2>Issued uniforms, IDs &amp; other items</h2></div><a class="button small" href="<?=e(url('/uniform-id'))?>">View inventory</a></div><div class="table-card"><table><thead><tr><th>Item</th><th>Type</th><th>Issued</th><th>Returned</th><th>Outstanding</th><th>Status</th></tr></thead><tbody><?php foreach($inventoryIssues as $issue):?><?php $typeLabel=['uniform'=>'Uniform','id_card'=>'ID card','other'=>'Other item'][$issue['item_type']]??'Other item';$outstanding=(int)$issue['quantity']-(int)$issue['returned_quantity'];?><tr><td><strong><?=e($issue['item_name'])?></strong><?php if($issue['variant']):?> <span class="badge"><?=e($issue['variant'])?></span><?php endif;?><br><small><?=e($issue['sku'])?></small></td><td><?=e($typeLabel)?></td><td><?=(int)$issue['quantity']?> <?=e($issue['unit'])?><br><small><?=e($issue['issued_on'])?></small></td><td><?=(int)$issue['returned_quantity']?></td><td><strong><?=$outstanding?></strong></td><td><span class="badge"><?=e(str_replace('_',' ',$issue['status']))?></span></td></tr><?php endforeach;?><?php if(!$inventoryIssues):?><tr><td colspan="6" class="empty">No uniforms, IDs, or other inventory items assigned.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?>
</div>
